namespace {bool liability(const std::string&type){return type=="Credit Card"||type=="Loan"||type=="Other Liability";}std::string clipped(std::string value,std::size_t n){return value.size()>n?value.substr(0,n-3)+"...":value;}std::string monthStart(){return FinanceService::currentMonth()+"-01";}std::optional<std::int64_t>optionalAmount(const std::string&value){if(value.empty())return{};return parseMoneyMinor(value,Currency::fromCode("USD"));}}
