void Shell::renderFinanceCalculator(){renderFinanceHeader("FINANCIAL CALCULATORS");const char*items[]={"SAVINGS","LOAN","CARD PAYOFF","TIP","PERCENTAGE"};for(int i=0;i<5;++i)if(button({60,260.0f+i*92,270,65},items[i],i==0)){financeDraftType_=items[i];financeCalculatorResult_.clear();if(i==3){openTextPrompt("BILL AMOUNT","",[this](const std::string&bill){financeDraftAmount_=bill;openTextPrompt("TIP PERCENT","20",[this](const std::string&tip){auto b=parseMoneyMinor(financeDraftAmount_,Currency::fromCode("USD"));try{double p=std::stod(tip);if(!b)throw std::runtime_error("amount");const auto tipMinor=static_cast<std::int64_t>(*b*p/100.0);financeCalculatorResult_="TIP "+financeAmount(tipMinor)+"  TOTAL "+financeAmount(*b+tipMinor);}catch(...){toast("INVALID CALCULATION");}},InputType::Number);},InputType::Number);}else if(i==4){openTextPrompt("VALUE","",[this](const std::string&value){financeDraftAmount_=value;openTextPrompt("PERCENT","",[this](const std::string&p){try{financeCalculatorResult_=std::format("{}% OF {} = {:.2f}",std::stod(p),std::stod(financeDraftAmount_),std::stod(financeDraftAmount_)*std::stod(p)/100.0);}catch(...){toast("INVALID CALCULATION");}},InputType::Number);},InputType::Number);}else{openTextPrompt(i==0?"STARTING AMOUNT":i==1?"LOAN AMOUNT":"CARD BALANCE","",[this,i](const std::string&amount){financeDraftAmount_=amount;openTextPrompt("APR PERCENT","",[this,i](const std::string&apr){financeDraftInstitution_=apr;openTextPrompt(i==0?"MONTHLY CONTRIBUTION":"MONTHLY PAYMENT","",[this,i](const std::string&monthly){try{double principal=std::stod(financeDraftAmount_),rate=std::stod(financeDraftInstitution_)/1200.0,pay=std::stod(monthly);if(i==0){openTextPrompt("YEARS","",[this,principal,rate,pay](const std::string&years){try{int months=static_cast<int>(std::stod(years)*12);double value=principal;for(int m=0;m<months;++m)value=value*(1+rate)+pay;financeCalculatorResult_=std::format("ESTIMATED VALUE  ${:.2f}",value);}catch(...){toast("INVALID CALCULATION");}},InputType::Number);return;}if(pay<=principal*rate)throw std::runtime_error("Payment too low");int months=0;double balance=principal,interest=0;while(balance>0.005&&months<1200){double charge=balance*rate;interest+=charge;balance=std::max(0.0,balance+charge-pay);++months;}financeCalculatorResult_=std::format("{} MONTHS  /  INTEREST ${:.2f}",months,interest);}catch(...){toast("PAYMENT DOES NOT COVER INTEREST");}},InputType::Number);},InputType::Number);},InputType::Number);}}panel({365,260,315,430});label(390,290,"LOCAL RESULT",2.1f,Theme::Gold);label(390,345,clipped(financeCalculatorResult_.empty()?"SELECT A CALCULATOR":financeCalculatorResult_,27),2.2f);sublabel(390,405,"CALCULATIONS NEVER LEAVE");sublabel(390,435,"THIS DEVICE");}
void Shell::renderFinanceCategories(){renderFinanceHeader("CATEGORIES");if(button({470,170,210,54},"NEW CATEGORY",true))openTextPrompt("CATEGORY NAME","",[this](const std::string&name){financeDraftName_=name;openTextPrompt("TWO-LETTER ICON","OT",[this](const std::string&icon){try{finance_.createCategory(financeDraftName_,icon);toast("CATEGORY CREATED");}catch(const std::exception&e){toast(clipped(e.what(),40));}},InputType::Text,2);});auto rows=finance_.categories(true);const float maxScroll=std::max(0.0f,rows.size()*76.0f-800);financeScroll_=std::clamp(financeScroll_,0.0f,maxScroll);for(std::size_t i=0;i<rows.size();++i){float y=245+i*76-financeScroll_;if(y<225||y>1040)continue;panel({40,y,640,64});label(58,y+16,rows[i].icon+"  "+clipped(rows[i].name,25),2.3f,rows[i].hidden?Theme::Muted:Theme::Ink);if(button({505,y+10,150,44},rows[i].hidden?"SHOW":"HIDE"))finance_.hideCategory(rows[i].id,!rows[i].hidden);if(!rows[i].builtIn&&hit({40,y,450,64})){openTextPrompt("RENAME CATEGORY",rows[i].name,[this,id=rows[i].id](const std::string&name){try{finance_.renameCategory(id,name);toast("CATEGORY RENAMED");}catch(const std::exception&e){toast(clipped(e.what(),40));}});}}}
void Shell::renderFinanceSettings(){renderFinanceHeader("SETTINGS");auto settings=finance_.settings();const bool busy=financeJob_.valid();float y=230-financeScroll_;auto row=[&](const std::string&text){Rect r{40,y,640,60};const bool pressed=y>210&&y<1060&&button(r,text);y+=72;return pressed;};if(row("DEFAULT CURRENCY: "+settings.defaultCurrency))openTextPrompt("DEFAULT CURRENCY",settings.defaultCurrency,[this](const std::string&v){auto s=finance_.settings();s.defaultCurrency=Currency::fromCode(v).code;finance_.saveSettings(s);},InputType::Text,3);if(row("START OF WEEK: "+settings.weekStart)){settings.weekStart=settings.weekStart=="Monday"?"Sunday":"Monday";finance_.saveSettings(settings);}if(row("CUSTOMIZE HOME CARDS"))financeDashboardPrompt_=true;if(row(std::string("HIDE BALANCES: ")+(settings.hideBalances?"ON":"OFF"))){settings.hideBalances=!settings.hideBalances;finance_.saveSettings(settings);}if(row(std::string("AUTHENTICATION: ")+(settings.requireAuthentication?"REQUIRED":"OFF"))){if(!security_.hasDevicePin()){openTextPrompt("CREATE DEVICE PIN","",[this](const std::string&pin){if(security_.setDevicePin(pin)){auto s=finance_.settings();s.requireAuthentication=true;finance_.saveSettings(s);financeSecurity_.configure(s);toast("DEVICE PIN CREATED");}else toast("PIN MUST BE 4-12 DIGITS");},InputType::Password,12);}else{settings.requireAuthentication=!settings.requireAuthentication;finance_.saveSettings(settings);financeSecurity_.configure(settings);}}if(row("AUTO-LOCK: "+settings.autoLock)){const std::string values[]={"Immediately","1 minute","5 minutes","Never"};auto it=std::ranges::find(values,settings.autoLock);settings.autoLock=values[(it==std::end(values)?0:(std::distance(std::begin(values),it)+1)%4)];finance_.saveSettings(settings);financeSecurity_.configure(settings);}if(row(std::string("BILL NOTIFICATIONS: ")+(settings.notificationsEnabled?"ON":"OFF"))){settings.notificationsEnabled=!settings.notificationsEnabled;finance_.saveSettings(settings);}if(row(std::string("NOTIFICATION PREVIEWS: ")+(settings.notificationPreviews?"ON":"PRIVATE"))){settings.notificationPreviews=!settings.notificationPreviews;finance_.saveSettings(settings);}if(y>210&&y<1060){if(button({40,y,310,60},busy?"WORKING...":"EXPORT CSV")&&!busy)financeJob_=std::async(std::launch::async,[this]{auto p=financeFiles_.exportTransactionsCsv("Documents/Finance/transactions.csv");return"EXPORTED "+p.filename().string();});if(button({370,y,310,60},busy?"WORKING...":"EXPORT JSON")&&!busy)financeJob_=std::async(std::launch::async,[this]{financeFiles_.exportEverythingJson("Documents/Finance/finance.json");return std::string("FINANCE JSON EXPORTED");});}y+=72;if(y>210&&y<1060){if(button({40,y,310,60},busy?"WORKING...":"CREATE BACKUP")&&!busy)financeJob_=std::async(std::launch::async,[this]{financeFiles_.createBackup("Documents/Finance/finance-backup.pinefinance");return std::string("BACKUP CREATED");});if(button({370,y,310,60},"RESTORE BACKUP")&&!busy)financeRestorePrompt_=true;}y+=72;if(y>210&&y<1060){if(button({40,y,310,60},"IMPORT CSV")&&!busy)beginFinanceImport();if(button({370,y,310,60},"LOCK NOW")){financeSecurity_.lock();dismissInput();}}y+=72;if(row("MANAGE CATEGORIES")){financeView_=FinanceView::Categories;financeScroll_=0;}if(y>210&&y<1060){panel({40,y,640,85});label(60,y+12,"DATABASE",2.1f,Theme::Gold);sublabel(60,y+43,"SCHEMA "+std::to_string(finance_.database().schemaVersion())+" / SQLITE WAL / LOCAL ONLY");}y+=97;if(row("ERASE ALL FINANCE DATA"))financeErasePrompt_=true;financeScroll_=std::clamp(financeScroll_,0.0f,std::max(0.0f,y+financeScroll_-1040));}
