  else if(financeTypePicker_){label(80,285,"WHAT TYPE OF ACCOUNT?",3.3f,Theme::Gold);const char*types[]={"Checking","Savings","Cash","Credit Card","Loan","Investment","Other Asset","Other Liability"};for(int i=0;i<8;++i)if(button({75+(i%2)*300.0f,350+(i/2)*110.0f,270,78},types[i],i<3)){financeTypePicker_=false;beginFinanceAccount(types[i]);}if(button({235,830,250,50},"CANCEL"))financeTypePicker_=false;}
